#!/usr/bin/env node
/**
 * One-off script: insert 3 hand-crafted SEO cornerstone blog posts into SQLite.
 *
 * Usage:
 *   node scripts/insert-seo-pillar-posts.js [path/to/ily.sqlite]
 *
 * Defaults to `data/ily.sqlite` relative to this script's parent directory.
 * Safe to re-run — posts are keyed by slug; if a slug already exists the
 * script skips inserting that post but still upserts the EN translation.
 */

const path = require("node:path");
const Database = require("better-sqlite3");

const dbPath =
  process.argv[2] || path.resolve(__dirname, "..", "data", "ily.sqlite");

const db = new Database(dbPath);
db.pragma("journal_mode = WAL");

// -- Helpers ----------------------------------------------------------------

function unescapeHtmlEntities(str) {
  // The generator agent returned entity-escaped HTML (&lt;p&gt;…). Unescape
  // the handful of entities it uses before we store. Intentionally narrow:
  // we don't want to touch real entities a human author might have put in.
  return String(str)
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&"); // must be last
}

function countWords(html) {
  const text = String(html).replace(/<[^>]+>/g, " ");
  const words = text.trim().split(/\s+/).filter(Boolean);
  return words.length;
}

